-- BHUMI NURSING COLLEGE
-- COMPLETE COURSE-WISE SYLLABUS/TOPIC CHAPTER STRUCTURE
-- B.Sc Nursing: 8 semesters; GNM: 3 years; ANM: 2 years (annual structure)
-- These are syllabus-aligned study units/topics, NOT copies of copyrighted textbook chapters.

create table if not exists public.library_chapters (
  id bigint generated by default as identity primary key,
  course text not null check (course in ('ANM','GNM','B.Sc Nursing')),
  year_level text not null,
  semester text,
  subject text not null,
  chapter_no integer not null,
  chapter_title text not null,
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

alter table public.library_materials add column if not exists chapter_id bigint references public.library_chapters(id) on delete set null;
create unique index if not exists library_chapters_unique_idx on public.library_chapters(course,year_level,coalesce(semester,''),subject,chapter_no);
create index if not exists library_chapters_course_year_idx on public.library_chapters(course,year_level);
create index if not exists library_chapters_subject_idx on public.library_chapters(subject);
create index if not exists library_materials_chapter_idx on public.library_materials(chapter_id);
alter table public.library_chapters enable row level security;
drop policy if exists "students read active chapters" on public.library_chapters;
drop policy if exists "admins manage chapters" on public.library_chapters;
create policy "students read active chapters" on public.library_chapters for select to authenticated using (is_active=true);
create policy "admins manage chapters" on public.library_chapters for all to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
grant select on public.library_chapters to anon, authenticated;
grant insert,update,delete on public.library_chapters to authenticated;

